[Form]
public class METCBCTInvoiceForm extends FormRun
{
    // CB411_412_ChargeThrough
    NumberSeqFormHandler numberSeqFormHandler;


}

    /// <summary>
    /// CB411_412_ChargeThrough handling number sequence
    /// </summary>
    /// <returns><c>NumberSeqFormHandler</c> object</returns>
    NumberSeqFormHandler numberSeqFormHandler()
    {
        if (!numberSeqFormHandler)
        {
            numberSeqFormHandler = NumberSeqFormHandler::newForm(VendParameters::METnumRefCBCTNumber().NumberSequenceId,
                                                                 element,
                                                                 InvoiceHeaderTable_ds,
                                                                 fieldNum(METCBCTInvoiceHeaderTable, Number)
                                                                );
        }

        return numberSeqFormHandler;
    }

    /// <summary>
    /// CB411_412_ChargeThrough handling number sequence
    /// </summary>
    void close()
    {
        if (numberSeqFormHandler)
        {
            numberSeqFormHandler.formMethodClose();
        }

        super();
    }

        /// <summary>
        /// Active method to set form controls and fields
        /// </summary>
        /// <returns> int value of the form object </returns>
        public int active()
        {
            int ret;
        
            ret = super();

            boolean isStatusCreated = InvoiceHeaderTable.Status == METCBCTInvoiceStatus::Created ? true : false;

            METCBCTInvoicePosting.enabled(isStatusCreated);
            METCBCTInvoiceLinesCreation.enabled(isStatusCreated);
            InvoiceHeaderTable_ds.allowEdit(isStatusCreated);
            InvoiceHeaderTable_ds.allowDelete(isStatusCreated);
            InvoiceLine_ds.allowEdit(isStatusCreated);
            InvoiceLine_ds.allowCreate(isStatusCreated);
            InvoiceLine_ds.allowDelete(isStatusCreated);
        
            return ret;
        }

/// <summary>
/// CB411_412_ChargeThrough handling number sequence
/// </summary>
/// <param name = "_append">Append</param>
public void create(boolean _append = false)
{
    element.numberSeqFormHandler().formMethodDataSourceCreatePre();
    super(_append);
    element.numberSeqFormHandler().formMethodDataSourceCreate();
}

/// <summary>
/// CB411_412_ChargeThrough handling number sequence
/// </summary>
public void linkActive()
{
    element.numberSeqFormHandler().formMethodDataSourceLinkActive();
    super();
}

        /// <summary>
        /// CB411_412_ChargeThrough handling number sequence
        /// </summary>
        /// <returns>True if validation successful; otherwise, false.</returns>
        public boolean validateWrite()
        {
            boolean ret;
        
            ret = super();
        
            ret = element.numberSeqFormHandler().formMethodDataSourceValidateWrite(ret) && ret;

            return ret;
        }

        /// <summary>
        /// CB411_412_ChargeThrough handling number sequence
        /// </summary>
        public void delete()
        {
            ttsbegin;

            element.numberSeqFormHandler().formMethodDataSourceDelete();
            
            super();

            ttscommit;
        }

        /// <summary>
        /// CB411_412_ChargeThrough handling number sequence
        /// </summary>
        public void write()
        {
            ttsbegin;

            element.numberSeqFormHandler().formMethodDataSourceWrite();
            
            super();

            ttscommit;
        }

/// <summary>
/// Initialise values for record
/// </summary>
public void initValue()
{
    super();
    // This toggle will automatically be set to yes if the invoice was entered manually by the user on the overview screen
    InvoiceHeaderTable.ManuallyCreated = NoYes::Yes;
}

        /// <summary>
        /// Init value 
        /// </summary>
        public void initValue()
        {
            METVendTable        metVendTable;
            METVendParameters   metVendParameters = METVendParameters::find();
            CustTable           custTable = CustTable::find(InvoiceHeaderTable.CustomerAccount);

            select firstonly metVendTable where metVendTable.AccountNum == InvoiceHeaderTable.VendorAccount;
            super();
            
            //Default item from the service item defined on the vendor
            // CB411_412_ChargeThrough
            if (InvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
            {
                InvoiceLine.ItemId = metVendTable.ChargeThroughServiceItemId;
            }
            else
            {
                InvoiceLine.ItemId = metVendTable.CrossDockServiceItemId;
            }
            InvoiceLine.TaxItemGroup = InventTableModule::find(InvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
            InvoiceLine.TaxGroup = metVendParameters.CreateLineGSTGroup;
            InvoiceLine.InventSiteId = custTable.InventSiteId;
            InvoiceLine.InventLocationId = custTable.InventLocation;
            // CB411_412_ChargeThrough call modifiedField so it sets financial dimension
            //InvoiceLine.FinancialDimension = METCBCTInvoiceLine::initFinancialDimension(metVendTable.ChargeThroughServiceItemId,InvoiceHeaderTable.FinancialDimension);
            InvoiceLine.modifiedField(fieldNum(METCBCTInvoiceLine, ItemId));
        }

            /// <summary>
            /// Modified line type 
            /// </summary>
            public void modified()
            {
                super();

                switch(InvoiceLine.VendCustType)
                {
                    case METCBCTVendCust::Vend:
                        InvoiceLine.TaxGroup = VendTable::find(InvoiceHeaderTable.VendorAccount).TaxGroup;
                        break;

                    case METCBCTVendCust::Cust:
                        InvoiceLine.TaxGroup = CustTable::find(InvoiceHeaderTable.CustomerAccount).TaxGroup;
                        break;
                }
            }

        /// <summary>
        /// CustFreeTextInvoice clicked method
        /// </summary>
        public void clicked()
        {
            MenuFunction menuFunction;
            Args args = new Args();
            args.record(CustInvoiceJour::findFromSalesId(InvoiceHeaderTable.RefSalesId)); // to send whole table as parameter
            args.caller(this);
            menuFunction = new MenuFunction(menuitemDisplayStr(CustTrans), MenuItemType::Display);
            menuFunction.run(args);

        }

/// <summary>
/// Create new invoice line of type customer
/// </summary>
public void clicked()
{
    //super();
    InvoiceLine_ds.create();
    InvoiceLine.VendCustType = METCBCTVendCust::Cust;
}
